# Adamant Will (FDN): "Target creature gets +2/+2 and gains indestructible until end of turn."
# Shape: M21 Sure Strike's B5b-seq-modpt-firststrike (one TARGET slot shared by the two steps),
# with +2/+2 and Basri Ket's INDESTRUCTIBLE grant.
creature = Selector(
    count=QConst(value=1),
    mode=SelectorMode.TARGET,
    filter=FAtom(pred=FAtomPred.TYPE_EQ, string_value='Creature'),
    zones=(Zone(kind=ZoneKind.BATTLEFIELD, controller=ControllerRef.ANY),),
)
abilities = [
    SpellAbility(
        kind=SpellKind.INSTANT,
        effect=Seq(
            steps=(
                A(Verb.MODIFY_PT, {
                    'duration': DurationEot(),
                    'power': PtDelta(direction=PtDirection.INCREASE, magnitude=QConst(value=2)),
                    'target': creature,
                    'toughness': PtDelta(direction=PtDirection.INCREASE, magnitude=QConst(value=2)),
                }),
                A(Verb.GRANT_ABILITY, {
                    'ability': KeywordAbility(keyword=Keyword.INDESTRUCTIBLE),
                    'duration': DurationEot(),
                    'target': creature,
                }),
            ),
        ),
    ),
]
